// Things the TypeScript files use but don't define.

/** index.html (inline, so build_apk.py and publish.py can read it): the app version. */
declare const APP: { code: number; name: string };

/** audio.js (generated by voice/pack.py): base64 Opus clips and spoken-name aliases. */
declare const CLIPS: Record<string, string>;
declare const NAME_ALIAS: Record<string, string>;

/** The native Android bridge (build/app_dex.py). Missing in a browser, so always check before calling. */
interface NativeNet {
  start(port: number): void; put(k: string, v: string): void; take(): string | null; clear(): void;
  ip(): string; running(): boolean; keep(on: boolean): void;
  share(text: string): void; copy(text: string): void; open(url: string): void;
  saveApk(b64: string): boolean; install(): void;
}
declare const Net: NativeNet;
interface Window { Net?: NativeNet; webkitAudioContext?: typeof AudioContext }
